def solve_c1(grid, h, w):
    bg = 8
    mint = 3
    mark = 2
    out = [[bg] * w for _ in range(h)]

    # Store min markers
    for c in range(w):
        if grid[0][c] == mint:
            out[0][c] = mint
        if grid[h-1][c] == mint:
            out[h-1][c] = mint

    # Top band (15-18): fill rows 1 to h-1
    for c in [15, 16, 17, 18]:
        for r in range(1, h):
            out[r][c] = mint

    # Bottom band (5-8)
    for c in range(5, 9):
        first_max = None
        if c == 5:
            first_max = 3
        elif c == 6:
            first_max = 2
        else:
            first_max = None

        if first_max is not None:
            for r in range(first_max, h-1):
                if grid[r][c] == mark:
                    out[r][c] = 4
                else:
                    out[r][c] = mint

    return out

